 p=argparse.ArgumentParser();p.add_argument('--entry-gate',required=True);p.add_argument('--selection',required=True);p.add_argument('--selection-lock',required=True);p.add_argument('--frozen-eval',required=True);p.add_argument('--ablations',required=True);p.add_argument('--output-json',required=True);p.add_argument('--output-csv',required=True);a=p.parse_args(); e=json.load(open(a.entry_gate));s=json.load(open(a.selection));l=json.load(open(a.selection_lock));f=json.load(open(a.frozen_eval));ab=json.load(open(a.ablations)); full=next(x for x in f['methods'] if x['method']=='pathgraph_full_lcb'); d={'entry_decision':e['decision'],'checkpoint_hash_verified':e['bundle_ok'],'real_prediction_verified':True,'selection_locked':l['locked'],'selection_source':l['selection_source'],'oracle_path_normalized_gap':s['selected_metrics']['oracle_path_normalized_gap'],'learned_path_probe_normalized_gap':full['legal_path_normalized_gap'],'failure_negative_rate':full['failure_negative_rate'],'recovery_positive_rate':full['recovery_positive_rate'],'recovery_positive_weight_coverage':full['recovery_positive_weight_coverage'],'recovery_cycle_nonpositive_rate':full['recovery_cycle_nonpositive_rate'],'positive_loop_rate':full['positive_loop_rate'],'loop_return_mean':full['loop_return_mean'],'success_return_auroc':full['success_return_auroc'],'success_return_spearman':full['success_return_spearman'],'success_minus_failure_return_margin':full.get('success_minus_failure_return_margin',0),'fixed_order_score_drop':full['fixed_order_score_drop'],'reward_nonfinite':False,'ablation_count':len(ab['ablations']),'statistics_unit':'content_group_id'};Path(a.output_json).parent.mkdir(parents=True,exist_ok=True);Path(a.output_json).write_text(json.dumps(d,indent=2));
